import{_ as e,H as l,f as a,i as d}from"./chunks/framework.DLd0CbzH.js";const x=JSON.parse('{"title":"Статус разработки — Agelto","description":"","frontmatter":{"type":"dev-status","tags":["agelto","status","progress"],"created":"2026-05-31T00:00:00.000Z","updated":"2026-06-14T00:00:00.000Z"},"headers":[],"relativePath":"03_Dev/Dev_Status.md","filePath":"03_Dev/Dev_Status.md"}'),r={name:"03_Dev/Dev_Status.md"};function s(i,t,n,g,o,y){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="статус-разработки-—-agelto" tabindex="-1">Статус разработки — Agelto <a class="header-anchor" href="#статус-разработки-—-agelto" aria-label="Permalink to &quot;Статус разработки — Agelto&quot;">​</a></h1><div class="info custom-block github-alert"><p class="custom-block-title">Связанные документы</p><p>← [[BRD (Agelto)]] | ← [[Architecture_Agelto]] | → [[ADR-001_Catalog_From_TcenZor]]</p></div><div class="note custom-block github-alert"><p class="custom-block-title">Снято со scope Agelto</p><p>Построение собственного эталонного каталога/MDM (нормативка КТРУ/КСР/ГОСТ/ОКПД2) <strong>снимается</strong> с Agelto — приходит из [[TcenZor]] по API ([[ADR-001_Catalog_From_TcenZor|ADR-001]]). Фокус Agelto — парсинг смет + матчинг к эталону + golden dataset вердиктов.</p></div><hr><h2 id="реализовано" tabindex="-1">Реализовано <a class="header-anchor" href="#реализовано" aria-label="Permalink to &quot;Реализовано&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Компонент</th><th style="text-align:left;">Статус</th></tr></thead><tbody><tr><td style="text-align:left;">Кроулер zakupki.gov.ru (EisCrawlingService)</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Дробление по датам и ценам</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Загрузка вложений с ротацией прокси</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">DocumentAnalysis: загрузка PDF в Gemini Files API</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">DocumentAnalysis: context cache (6-часовой TTL)</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">DocumentAnalysis: иерархия шагов (parent_id)</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">4-стадийный pipeline: Bus::chain + idempotency guards</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">State machine AnalysisStatus (11 статусов) + лог переходов</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Telegram-алерты о сбоях пайплайна</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Чанковый EstimateAnalysis (80 строк/чанк)</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">PromptRules: управление инструкциями через Filament</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">SmetaParserService: шапка Excel-сметы через Gemini</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">SmetaParserService: чанковый парсинг строк сметы</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Схема данных Order/Lot/PurchaseObject</td><td style="text-align:left;">✅ Миграции</td></tr><tr><td style="text-align:left;">Схема данных OrderCustomer (ИНН/КПП/ОГРН)</td><td style="text-align:left;">✅ Миграции</td></tr><tr><td style="text-align:left;">Sys: прокси-пул</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Sys: логирование</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Docker: dev + prod compose (Swarm secrets)</td><td style="text-align:left;">✅ Готово</td></tr><tr><td style="text-align:left;">Filament: базовый admin</td><td style="text-align:left;">✅ Скелет</td></tr><tr><td style="text-align:left;">Fortify auth + 2FA (TOTP)</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Pest v4 + architecture tests + larastan</td><td style="text-align:left;">✅ Рабочий</td></tr><tr><td style="text-align:left;">Редизайн схемы БД (Вариант A): единый error-блок, лизинг, <code>plt_crawler_runs</code>; удалены <code>plt_parsing_*</code></td><td style="text-align:left;">✅ Выполнено (<code>AUDIT.md</code>)</td></tr></tbody></table><hr><h2 id="в-разработке" tabindex="-1">В разработке <a class="header-anchor" href="#в-разработке" aria-label="Permalink to &quot;В разработке&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Компонент</th><th style="text-align:left;">Статус</th></tr></thead><tbody><tr><td style="text-align:left;">Синхронизация эталонного каталога из [[TcenZor]] (реплика строительного среза)</td><td style="text-align:left;">🔧 Не начата (новое, ADR-001)</td></tr><tr><td style="text-align:left;">Семантический матчинг (pgvector): смета → эталон → коллекция</td><td style="text-align:left;">🔧 Не начат</td></tr><tr><td style="text-align:left;">Клиентские коллекции (прайс-лист клиента-поставщика)</td><td style="text-align:left;">🔧 Не начат</td></tr><tr><td style="text-align:left;">Lead Scorer (ранжирование)</td><td style="text-align:left;">🔧 Не начат</td></tr><tr><td style="text-align:left;">CRM-интеграция (Bitrix24/amoCRM)</td><td style="text-align:left;">🔧 Не начата</td></tr><tr><td style="text-align:left;">Frontend Radar / Smeta Viewer</td><td style="text-align:left;">🔧 Не начат</td></tr><tr><td style="text-align:left;">RBAC (роли Admin/Client/Manager/Analyst)</td><td style="text-align:left;">🔧 Не начат (Fortify ✅)</td></tr><tr><td style="text-align:left;">Биллинг / учёт квот (F-MON-1/3 — Must Have!)</td><td style="text-align:left;">❌ Не начат</td></tr><tr><td style="text-align:left;">Мультитенантность (схема не выбрана, T4)</td><td style="text-align:left;">❌ Не начата</td></tr><tr><td style="text-align:left;">Observability: метрики, SLO (есть только Telegram-алерты)</td><td style="text-align:left;">❌ Не начата</td></tr><tr><td style="text-align:left;">Backup / DR (RPO/RTO не определены, T7)</td><td style="text-align:left;">❌ Не начат</td></tr><tr><td style="text-align:left;">Лингвистический комплаенс (лат↔кир)</td><td style="text-align:left;">❌ Планируется v2</td></tr><tr><td style="text-align:left;">LayoutLMv3 / OCR для сканов</td><td style="text-align:left;">❌ Планируется v2</td></tr><tr><td style="text-align:left;">Мониторинг результата закупки (победитель, протокол итогов, сценарии возврата)</td><td style="text-align:left;">❌ Предложено ([[ADR-002_Winner_Tracking_And_Monitoring]])</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">Разрыв требования ↔ код</p><p>Матчинг (F-MATCH-*) — Must Have в [[BRD (Agelto)]], не начат — критический путь. Биллинг на пилоте — вручную (см. критерий MVP, [[BRD (Agelto)]] §1).</p></div>',10)])])}const c=e(r,[["render",s]]);export{x as __pageData,c as default};
